<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import type{FormInstance,FormRules}from'element-plus';import{ElMessage}from'element-plus';import http from'../api/http'
const rows=ref<any[]>([]),total=ref(0),loading=ref(false),dialog=ref(false),saving=ref(false),formRef=ref<FormInstance>();const query=reactive({page:1,page_size:10,keyword:''});const form=reactive({id:0,name:'',description:'',status:'active'})
const rules:FormRules={name:[{required:true,message:'请输入科室名称',trigger:'blur'},{min:2,max:80,message:'长度为2至80个字符',trigger:'blur'}],description:[{max:500,message:'介绍不能超过500字',trigger:'blur'}]}
async function load(){loading.value=true;try{const{data}=await http.get('/departments',{params:query});rows.value=data.results;total.value=data.count}finally{loading.value=false}}
function open(row?:any){Object.assign(form,row||{id:0,name:'',description:'',status:'active'});dialog.value=true}
async function save(){await formRef.value?.validate();saving.value=true;try{const body={name:form.name,description:form.description,status:form.status};form.id?await http.put(`/departments/${form.id}`,body):await http.post('/departments',body);ElMessage.success('保存成功');dialog.value=false;load()}finally{saving.value=false}}
onMounted(load)
</script>
<template><div><div class="page-title"><div><h1>科室管理</h1><p>维护医院科室基础资料</p></div><el-button type="primary" @click="open()">新增科室</el-button></div><el-card><div class="toolbar"><el-input v-model="query.keyword" clearable placeholder="输入科室名称" @keyup.enter="query.page=1;load()"/><el-button @click="query.page=1;load()">查询</el-button></div><el-table v-loading="loading" :data="rows"><el-table-column prop="name" label="科室名称"/><el-table-column prop="description" label="科室介绍" min-width="260"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.status==='active'?'success':'info'">{{row.status==='active'?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button></template></el-table-column></el-table><div class="pagination"><span>共 {{total}} 条</span><el-pagination v-model:current-page="query.page" v-model:page-size="query.page_size" layout="sizes,prev,pager,next" :total="total" @change="load"/></div></el-card><el-dialog v-model="dialog" :title="form.id?'编辑科室':'新增科室'" width="520px"><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><el-form-item label="科室名称" prop="name"><el-input v-model="form.name"/></el-form-item><el-form-item label="科室介绍" prop="description"><el-input v-model="form.description" type="textarea" :rows="4" maxlength="500" show-word-limit/></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio value="active">启用</el-radio><el-radio value="inactive">停用</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></div></template>
